import{_ as i,c as t,o as a,ag as r,j as n}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/installation.md","filePath":"de/guide/installation.md","lastUpdated":1794112334000}'),l={name:"de/guide/installation.md"};function o(s,e,d,h,u,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="nicasa-herunterladen" tabindex="-1">Nicasa herunterladen <a class="header-anchor" href="#nicasa-herunterladen" aria-label="Permalink to &quot;Nicasa herunterladen&quot;">​</a></h2><p>Nicasa ist ausschließlich für macOS über den Mac App Store erhältlich. Die App kostet 4,99 $ und bietet einen einmaligen Kauf mit Zugriff auf alle Funktionen.</p><h3 id="download-optionen" tabindex="-1">Download-Optionen <a class="header-anchor" href="#download-optionen" aria-label="Permalink to &quot;Download-Optionen&quot;">​</a></h3><ul><li><strong>Mac App Store</strong>: <a href="https://apps.apple.com/us/app/nicasa-image-viewer/id6756032669?mt=12" target="_blank" rel="noreferrer">Nicasa herunterladen</a> —— 4,99 $</li><li><strong>Chrome-Erweiterung</strong>: <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Kostenlose Chrome-Erweiterung</a> —— Kostenlos</li></ul><h2 id="installationsschritte" tabindex="-1">Installationsschritte <a class="header-anchor" href="#installationsschritte" aria-label="Permalink to &quot;Installationsschritte&quot;">​</a></h2><h3 id="installation-uber-den-mac-app-store" tabindex="-1">Installation über den Mac App Store <a class="header-anchor" href="#installation-uber-den-mac-app-store" aria-label="Permalink to &quot;Installation über den Mac App Store&quot;">​</a></h3><ol><li>Klicke auf den obigen Link „Nicasa herunterladen“ oder suche im Mac App Store nach „Nicasa“</li><li>Klicke auf „Laden“ oder „Kaufen“, um die App zu erwerben (4,99 $)</li><li>Die App wird automatisch heruntergeladen und installiert</li><li>Starte Nicasa aus dem Ordner „Programme“ oder über das Launchpad</li></ol><h3 id="installation-der-chrome-erweiterung" tabindex="-1">Installation der Chrome-Erweiterung <a class="header-anchor" href="#installation-der-chrome-erweiterung" aria-label="Permalink to &quot;Installation der Chrome-Erweiterung&quot;">​</a></h3><ol><li>Besuche die <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Seite im Chrome Web Store</a></li><li>Klicke auf „Zu Chrome hinzufügen“</li><li>Bestätige die Installation im Popup</li><li>Die Erweiterung wird deinem Browser hinzugefügt</li></ol><h4 id="demo-der-chrome-erweiterung" tabindex="-1">Demo der Chrome-Erweiterung <a class="header-anchor" href="#demo-der-chrome-erweiterung" aria-label="Permalink to &quot;Demo der Chrome-Erweiterung&quot;">​</a></h4>',11),n("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0"}},[n("iframe",{src:"https://www.youtube.com/embed/NJPweIr1J4s",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:"",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),r('<p><a href="https://www.youtube.com/watch?v=NJPweIr1J4s" target="_blank" rel="noopener">Ansehen: Kurzdemo der Nicasa Chrome-Erweiterung</a></p><h2 id="erster-start" tabindex="-1">Erster Start <a class="header-anchor" href="#erster-start" aria-label="Permalink to &quot;Erster Start&quot;">​</a></h2><p>Wenn du Nicasa zum ersten Mal startest:</p><ol><li>Du wirst aufgefordert, die nötigen Berechtigungen zu erteilen (Bildschirmaufnahme für Screenshots)</li><li>Die App durchsucht deinen Bilderordner nach Bildern</li><li>Du kannst sofort mit dem Durchsehen deiner Sammlung beginnen</li><li>Erwäge die Installation der Chrome-Erweiterung für ein besseres Weberlebnis</li></ol><h3 id="finder-sync-erweiterung" tabindex="-1">Finder-Sync-Erweiterung <a class="header-anchor" href="#finder-sync-erweiterung" aria-label="Permalink to &quot;Finder-Sync-Erweiterung&quot;">​</a></h3><p>Nicasa enthält eine Erweiterung für die Finder-Symbolleiste zur schnellen Bildverarbeitung:</p><ol><li>Gehe nach dem Start von Nicasa zu <strong>Systemeinstellungen</strong> → <strong>Erweiterungen</strong> → <strong>Finder-Erweiterungen</strong></li><li>Aktiviere <strong>Nicasa Finder Sync</strong></li><li>Rechtsklicke auf die Finder-Symbolleiste → <strong>Symbolleiste anpassen …</strong></li><li>Ziehe die Nicasa-Schaltfläche in die Symbolleiste</li></ol><p>So kannst du ausgewählte Bilder direkt aus dem Finder optimieren oder bearbeiten.</p><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to &quot;Systemanforderungen&quot;">​</a></h2><ul><li><strong>macOS</strong>: 10.13 oder neuer</li><li><strong>Speicherplatz</strong>: 54,5 MB freier Speicher</li><li><strong>Arbeitsspeicher</strong>: mindestens 4 GB RAM, 8 GB empfohlen</li></ul><h2 id="berechtigungen" tabindex="-1">Berechtigungen <a class="header-anchor" href="#berechtigungen" aria-label="Permalink to &quot;Berechtigungen&quot;">​</a></h2><p>Nicasa benötigt folgende Berechtigungen:</p><ul><li><strong>Bildschirmaufnahme</strong>: für die Screenshot-Funktion (kann später erteilt werden)</li><li><strong>Bedienungshilfen</strong>: für Funktionen des Overlay-Modus (optional)</li><li><strong>Dateien und Ordner</strong>: Zugriff auf den Bilderordner und von dir ausgewählte Verzeichnisse</li></ul><p>Du kannst diese Berechtigungen jederzeit unter Systemeinstellungen &gt; Datenschutz &amp; Sicherheit ändern.</p><h2 id="installationsprobleme-beheben" tabindex="-1">Installationsprobleme beheben <a class="header-anchor" href="#installationsprobleme-beheben" aria-label="Permalink to &quot;Installationsprobleme beheben&quot;">​</a></h2><p>Wenn bei der Installation Probleme auftreten:</p><ul><li>Stelle sicher, dass du Administrator-/Root-Rechte hast</li><li>Prüfe, ob dein System die Mindestanforderungen erfüllt</li><li>Versuche, die Datei erneut herunterzuladen</li><li>Stelle unter Linux sicher, dass die nötigen Abhängigkeiten installiert sind</li></ul><p>Weitere Hilfe findest du auf unserer <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">Issues-Seite</a>.</p>',18)])])}const p=i(l,[["render",o]]);export{m as __pageData,p as default};
